package main

import "testing"

func TestStartsFullAndDrains(t *testing.T) {
	b := NewTokenBucket(3, 1)
	for i := 0; i < 3; i++ {
		if !b.Allow(0) {
			t.Fatalf("expected allow at i=%d", i)
		}
	}
	if b.Allow(0) {
		t.Fatalf("expected deny once drained")
	}
}

func TestRefillsOverTime(t *testing.T) {
	b := NewTokenBucket(3, 1)
	for i := 0; i < 3; i++ {
		b.Allow(0)
	}
	if b.Allow(0.5) {
		t.Fatalf("expected deny at t=0.5")
	}
	if !b.Allow(1.0) {
		t.Fatalf("expected allow at t=1.0")
	}
	if b.Allow(1.0) {
		t.Fatalf("expected deny again immediately after")
	}
}

func TestRefillCapsAtCapacity(t *testing.T) {
	b := NewTokenBucket(2, 1)
	b.Allow(0)
	b.Allow(0)
	if !b.Allow(1000) || !b.Allow(1000) {
		t.Fatalf("expected 2 tokens available after long idle")
	}
	if b.Allow(1000) {
		t.Fatalf("expected refill capped at capacity")
	}
}

