package main

type TokenBucket struct {
	capacity   float64
	refillRate float64
	tokens     float64
	hasLast    bool
	last       float64
}

func NewTokenBucket(capacity, refillRate float64) *TokenBucket {
	return &TokenBucket{capacity: capacity, refillRate: refillRate, tokens: capacity}
}

func (b *TokenBucket) Allow(now float64) bool {
	if b.hasLast {
		elapsed := now - b.last
		b.tokens += elapsed * b.refillRate
		if b.tokens > b.capacity {
			b.tokens = b.capacity
		}
	}
	b.last = now
	b.hasLast = true
	if b.tokens >= 1 {
		b.tokens -= 1
		return true
	}
	return false
}

